Contract RepairService::approve(sid:Integer,rid:Integer,reject:Boolean,suggestion:String): ApprovalHistory {

            precondition:
          Repair.allInstances()->one(r: Repair | r.Id = rid) and Staff.allInstances()->one(s: Staff | s.Id = sid) and (reject = false or Repair.allInstances()->exists(r: Repair | r.Id = rid and Staff.allInstances()->exists(s: Staff | s.Id = sid and ((s.Role = 1 and r.Process = 0) or (s.Role = 2 and r.Process = 1) or (s.Role = 3 and r.Process = 2)))))

            postcondition:
          let r: Repair = Repair.allInstances()->any(x: Repair | x.Id = rid), s: Staff = Staff.allInstances()->any(y: Staff | y.Id = sid), oldHistory: Set(ApprovalHistory) = r.History@pre in result.oclIsNew() and result.StaffId = sid and result.Reject = reject and result.Suggestion = suggestion and oldHistory->excludes(result) and r.History->includes(result) and r.History->includesAll(oldHistory) and r.History->size() = oldHistory->size() + 1 and if reject = true then ((s.Role = 1 and r.Process@pre = 0 and r.Process = 1) or (s.Role = 2 and r.Process@pre = 1 and r.Process = 2) or (s.Role = 3 and r.Process@pre = 2 and r.Process = 3)) else r.Process = 5 endif and Repair.allInstances()->forAll(rr: Repair | rr.Id = rid or (rr.Process = rr.Process@pre and rr.History = rr.History@pre))

        }
